        Part(0,1.03f,0,.72f,.65f,.4f);Part(0,1.52f,0,.43f,.37f,.4f,new(.65f,.7f,.7f));Part(0,1.53f,-.215f,.33f,.08f,.025f,new(.1f,1,.9f),1);Part(-.46f,1.05f,0,.2f,.54f,.23f);Part(.46f,1.05f,-.2f,.2f,.5f,.23f);Part(.38f,1,-.52f,.2f,.2f,.7f,new(.35f,.45f,.5f));Part(-.21f,.4f,walk*.18f,.24f,.72f,.27f,new(.3f,.37f,.4f));Part(.21f,.4f,-walk*.18f,.24f,.72f,.27f,new(.3f,.37f,.4f));Part(-.21f,.1f,walk*.18f-.08f,.3f,.18f,.42f);Part(.21f,.1f,-walk*.18f-.08f,.3f,.18f,.42f);if(p.Invulnerable>0)Part(0,1.85f,0,.2f,.12f,.2f,new(.3f,.8f,1),1);
